    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/pm-spec",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "product",
    "web",
    "desktop",
    "prd",
    "spec",
    "product-spec",
